/*
 * A310408  Coordination sequence Gal.6.196.6 where Gal.u.t.v denotes the
 *          coordination sequence for a vertex of type v in tiling number t in
 *          the Galebach list of u-uniform tilings.
 * https://oeis.org/A310408
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(0) = 1 a(1) = 4 For n ≥ 2: a(n) = a(n-1) + 6 if n is one of 2,
 *            4, 8, 10, 13, 15, 19, 21, 24, 26, 30, 32, 35, 37, 41, 43, 46,
 *            48, … (the positions of +6 differences are generated by starting
 *            from 2 and repeatedly adding the cyclic increments 2, 4, 2, 3)
 *            a(n) = a(n-1) + 4 otherwise The sequence o...
 * Range:     u8 n <= 49, u16 n <= 49, u32 n <= 49, u64 n <= 49, u128 n <= 49,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)1;

    seq_t val = (seq_t)1;          /* a(0) */
    val += (seq_t)3;               /* a(1) */

    if (n == 1)
        return val;

    /* positions where the increment is 6 */
    idx_t next6 = 2;               /* first position of +6 */
    const idx_t inc[4] = {2, 4, 2, 3};
    int inc_pos = 0;

    for (idx_t i = 2; i <= n; ++i)
    {
        if (i == next6)
        {
            val += (seq_t)6;
            next6 += inc[inc_pos];
            inc_pos = (inc_pos + 1) & 3;  /* cycle through 0..3 */
        }
        else
        {
            val += (seq_t)4;
        }
    }
    return val;
}
